def closure(attrs, fds):  # fds: [(lhs 집합, rhs 집합)]
    result = set(attrs)
    changed = True
    while changed:
        changed = False
        for lhs, rhs in fds:
            if lhs <= result and not rhs <= result:
                result |= rhs  # 좌변 포함 → 우변 추가
                changed = True
    return result

def candidate_keys(R, fds):
    keys = []
    for k in range(1, len(R) + 1):  # 작은 조합부터
        for X in combinations(sorted(R), k):
            X = set(X)
            if any(key <= X for key in keys):
                continue  # 기존 키 포함 → 최소성 위반
            if closure(X, fds) == set(R):  # 유일성
                keys.append(X)
    return keys

canonical-cover.pseudocode:
def canonical_cover(fds):  # fds: [(lhs, rhs)] 집합 쌍
    # 1. 우변 단일화
    F = [(set(l), {a}) for l, r in fds for a in r]
    # 2. 좌변 무관 속성 제거
    for i, (lhs, rhs) in enumerate(F):
        for a in sorted(lhs):
            rest = lhs - {a}
            if rest and rhs <= closure(rest, F):
                lhs = rest  # a 없이도 우변 유도 가능
        F[i] = (lhs, rhs)
    # 3. 중복 종속 제거
    result = []
    for i, fd in enumerate(F):
        if fd in result:
            continue
        others = result + F[i + 1:]
        if not fd[1] <= closure(fd[0], others):
            result.append(fd)  # 다른 종속으로 유도 불가
    return result
